python3 - <<'PY'
import subprocess,sys
p=subprocess.run(['docker','logs','--tail','180','deploy-gaybbs-1'],capture_output=True,text=True,timeout=20)
s=(p.stdout+'\n'+p.stderr).lower()
if 'gaybbs_bot_ready' in s:sys.exit(101)
if 'gaybbs_startup_failed' in s:sys.exit(102)
if 'database_url_required' in s:sys.exit(103)
if 'invalid' in s and 'token' in s:sys.exit(104)
if 'migration' in s and ('failed' in s or 'error' in s):sys.exit(105)
if 'gaybbs_error' in s:sys.exit(106)
if p.returncode:sys.exit(107)
sys.exit(108)
PY
